@startuml

enum Unit {
  CELSIUS
  WATT
}

class HomeTec {}

class SensorController {}

class Apartment {
  + address : string
  + emailAddress : string
}

class Inhabitant {
  + username : string
  + password : string
  + hasAdministrativeRights : boolean
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

SensorController "1" -- "1" Apartment
Apartment "1" -- "1..*" Inhabitant
Apartment "1" -- "1..*" Room
Room "1" -- "1..*" Sensor
Sensor "1" *-- "0..*" MeasuredValue
SensorController "1" -- "0..*" Sensor
SensorController "1" -- "0..*" EMonitor

@enduml

